document.addEventListener('DOMContentLoaded',()=>{
 const tabs=[...document.querySelectorAll('[data-camera-workspace-target]')],panels=[...document.querySelectorAll('[data-camera-workspace]')];
 const activate=name=>{if(!panels.some(p=>p.dataset.cameraWorkspace===name))name='cameras';tabs.forEach(t=>t.classList.toggle('active',t.dataset.cameraWorkspaceTarget===name));panels.forEach(p=>p.classList.toggle('is-active',p.dataset.cameraWorkspace===name));try{sessionStorage.setItem('propertyhub.camera.workspace',name)}catch(e){}};
 let initial='cameras';try{initial=sessionStorage.getItem('propertyhub.camera.workspace')||'cameras'}catch(e){};activate(initial);tabs.forEach(t=>t.addEventListener('click',()=>activate(t.dataset.cameraWorkspaceTarget)));
 document.getElementById('cameraAreasExpand')?.addEventListener('click',()=>document.querySelectorAll('.camera-area-group').forEach(d=>d.open=true));document.getElementById('cameraAreasCollapse')?.addEventListener('click',()=>document.querySelectorAll('.camera-area-group').forEach(d=>d.open=false));
});
