<script>
(()=>{const modal=document.getElementById('adminCameraLiveModal'),video=document.getElementById('adminCameraLiveVideo'),img=document.getElementById('adminCameraLiveImage'),title=document.getElementById('adminCameraLiveTitle'),state=document.getElementById('adminCameraLiveState'),diag=document.getElementById('adminCameraLiveDiag'),loading=document.getElementById('adminCameraLiveLoading'),playBtn=document.getElementById('adminCameraLivePlay'),retry=document.getElementById('adminCameraLiveRetry'),accessBar=document.getElementById('adminCameraAccessBar'),accessControls=document.getElementById('adminCameraAccessControls'),accessState=document.getElementById('adminCameraAccessState');let id=0,wantsLive=false,player=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const pollAccess=async(correlation,button)=>{for(let n=0;n<10;n++){await new Promise(r=>setTimeout(r,800));try{const r=await fetch('<?=url('camera-access-command-status')?>&correlation='+encodeURIComponent(correlation)+'&t='+Date.now(),{credentials:'same-origin',cache:'no-store'});const x=await r.json();if(!r.ok)continue;if(x.status==='confirmed'){button.classList.remove('btn-warning');button.classList.add('btn-success');button.innerHTML='<i class="bi bi-check2-circle me-1"></i>'+esc(x.access_name||'Abierto');accessState.textContent='Apertura confirmada';setTimeout(()=>{button.disabled=false;},1200);return;}if(['failed','denied','timeout'].includes(x.status)){throw new Error(x.error||'La apertura no fue confirmada.');}}catch(err){accessState.textContent=err?.message||String(err);button.disabled=false;return;}}accessState.textContent='Comando enviado; confirmación pendiente.';button.disabled=false;};
const openAccess=async(point,button)=>{if(!point.can_open||button.disabled)return;button.disabled=true;button.classList.remove('btn-outline-success');button.classList.add('btn-warning');button.innerHTML='<span class="spinner-border spinner-border-sm me-1"></span>Abriendo '+esc(point.name);accessState.textContent='Enviando apertura sin detener el video…';try{const body=new URLSearchParams();body.set('_csrf',<?=json_encode(csrf_token(),JSON_UNESCAPED_SLASHES)?>);body.set('camera_id',String(id));body.set('access_point_id',String(point.id));const r=await fetch('<?=url('camera-access-open')?>',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:body.toString()});const x=await r.json();if(!r.ok||!x.ok)throw new Error(x.message||'No fue posible abrir.');accessState.textContent='Comando enviado · esperando confirmación';await pollAccess(x.correlation_uuid,button);}catch(err){button.classList.remove('btn-warning');button.classList.add('btn-outline-danger');button.innerHTML='<i class="bi bi-exclamation-triangle me-1"></i>'+esc(point.name);button.disabled=false;accessState.textContent=err?.message||String(err);}};
const loadAccess=async()=>{if(accessControls)accessControls.innerHTML='';if(accessBar)accessBar.style.display='none';if(accessState)accessState.textContent='';if(!id)return;try{const r=await fetch('<?=url('camera-associated-access')?>&camera_id='+encodeURIComponent(id)+'&t='+Date.now(),{credentials:'same-origin',cache:'no-store'});const x=await r.json();if(!r.ok||!x.ok||!Array.isArray(x.access_points)||!x.access_points.length)return;accessBar.style.display='';x.access_points.forEach(point=>{const b=document.createElement('button');b.type='button';b.className='btn btn-sm '+(point.can_open?'btn-outline-success':'btn-outline-secondary');b.disabled=!point.can_open;b.title=point.can_open?'Abrir mientras observa el video':(point.reason||'No disponible');b.innerHTML='<i class="bi bi-door-open me-1"></i>'+esc(point.name);b.addEventListener('click',()=>openAccess(point,b));accessControls.appendChild(b);});}catch(e){if(accessState)accessState.textContent='No se pudieron cargar los accesos asociados.';}};
const snapshot=()=>{if(!id)return;video.style.display='none';loading.style.display='none';if(playBtn)playBtn.style.display='none';img.style.display='block';img.src='<?=url('camera-snapshot')?>&id='+encodeURIComponent(id)+'&t='+Date.now();state.textContent='Snapshot seguro';};
const connect=async()=>{if(!id)return;if(player)await player.close();img.style.display='none';video.style.display='none';loading.style.display='block';diag.textContent='Solicitando configuración al Node…';if(!wantsLive){snapshot();return;}try{const r=await fetch('<?=url('camera-live-config')?>&id='+encodeURIComponent(id)+'&t='+Date.now(),{credentials:'same-origin',cache:'no-store'});const cfg=await r.json();if(!r.ok||!cfg.available)throw new Error(cfg.message||'Video en vivo no disponible.');diag.textContent='WHEP: '+cfg.whep_url+' · Codec: '+(cfg.codec||'desconocido');player=new PropertyHubWhepPlayer(video);
video.addEventListener('ph-webrtc-state',ev=>{const d=ev.detail||{};if(d.phase==='preference'){if(d.value==='quick-tunnel-hls-first'){state.textContent='Cloudflare Quick Tunnel · HLS seguro';diag.textContent='El Quick Tunnel publica HTTP/HTTPS; HLS se usa primero porque WHEP no garantiza un camino ICE público.';}else{state.textContent=d.value==='mobile-hls-first'?'Preferencia móvil: HLS':'Preferencia escritorio: WebRTC';diag.textContent='Transporte automático con fallback cruzado WebRTC/HLS.';}}else if(d.phase==='transport'&&String(d.value).startsWith('hls')){state.textContent='HLS seguro a través del Property Node';diag.textContent='HLS autenticado/proxy seguro a través del Node.';}else if(d.phase==='hls')state.textContent='HLS: '+(d.value||'');else state.textContent='WebRTC '+(d.phase||'')+': '+(d.value||'');},{passive:true});
video.addEventListener('ph-webrtc-needs-play',ev=>{loading.style.display='none';video.style.display='block';if(playBtn)playBtn.style.display='block';state.textContent='WebRTC conectado · reproducción esperando toque';diag.textContent='Safari/iOS puede requerir un gesto directo aunque WHEP/ICE ya estén conectados.';},{passive:true});
video.addEventListener('ph-webrtc-error',ev=>{state.textContent='Error '+(ev.detail||'WebRTC');},{once:true});
const started=await player.start(cfg);loading.style.display='none';video.style.display='block';if(started?.needs_user_play){if(playBtn)playBtn.style.display='block';state.textContent='Conectado · toca Reproducir video';}else{if(playBtn)playBtn.style.display='none';state.textContent='En vivo · '+String(started?.transport||cfg.transport||'WebRTC').toUpperCase()+' · '+(cfg.codec||'video')+' · '+(cfg.relay_name||'Media Relay');}}catch(err){state.textContent='En vivo no disponible: '+(err?.message||err);diag.textContent='Se muestra snapshot para confirmar que la cámara sigue accesible. Si el snapshot funciona, revise MediaMTX/ICE.';snapshot();}};
modal?.addEventListener('show.bs.modal',e=>{id=Number(e.relatedTarget?.dataset.cameraId||0);wantsLive=String(e.relatedTarget?.dataset.live||'0')==='1';title.textContent=e.relatedTarget?.dataset.cameraName||'Cámara';loadAccess();connect();});modal?.addEventListener('hidden.bs.modal',async()=>{if(player){await player.close();player=null;}video.style.display='none';img.style.display='none';if(playBtn)playBtn.style.display='none';loading.style.display='block';if(accessControls)accessControls.innerHTML='';if(accessBar)accessBar.style.display='none';});playBtn?.addEventListener('click',async()=>{if(!player)return;const ok=await player.requestPlay(true);if(ok){playBtn.style.display='none';state.textContent='En vivo';}});retry?.addEventListener('click',connect);})();
</script>
<?php if(can('integrations.manage')):?><div class="modal fade" id="cameraModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><form method="post" action="<?=url('camera-save')?>"><?=csrf_field()?><input type="hidden" name="id" id="cameraId"><div class="modal-header"><div><h5 class="modal-title mb-0">Cámara / canal</h5><small id="cameraSourceNote" class="text-body-secondary"></small></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3">
<div class="col-md-6"><label class="form-label">Nombre administrativo</label><input class="form-control" name="name" id="cameraName" required><div id="cameraEdgeNameSync" class="mt-2" style="display:none"><label class="form-check mb-1"><input class="form-check-input" type="checkbox" name="follow_edge_name" id="cameraFollowEdgeName"><span class="form-check-label"><strong>Mantener sincronizado con el nombre del Agent</strong></span></label><small class="text-body-secondary">Nombre técnico actual: <span id="cameraEdgeTechnicalName">—</span>. Si desmarca esta opción, el Node conservará un nombre visible propio aunque el Agent cambie.</small></div></div>
<div class="col-md-6"><label class="form-label">Nombre para residentes</label><input class="form-control" name="resident_name" id="cameraResidentName" placeholder="Ej. Lobby, Entrada principal"><div class="form-text">Si queda vacío, Property App usa el nombre administrativo.</div></div>
<div class="col-md-4"><label class="form-label">Visibilidad residente</label><select class="form-select" name="resident_visibility" id="cameraVisibility"><option value="none">No visible</option><option value="all">Todos los residentes autorizados</option><option value="property_scope">Según propiedad/unidad vinculada</option></select><div class="form-text">Esto define visibilidad; la ubicación física es independiente.</div></div>
<div class="col-md-5"><label class="form-label">Ubicación estructural</label><select class="form-select" name="property_id" id="cameraProperty"><option value="">Sin ubicación estructural</option><?php foreach($properties as $p):?><option value="<?=e($p['id'])?>"><?=e($p['label']??$p['name'])?> · <?=e(property_type_label((string)$p['property_type']))?></option><?php endforeach;?></select><div class="form-text">Ej.: Sótano S3, Elevado 1, Planta baja. Los contenedores que no admiten recursos no aparecen.</div></div>
<div class="col-md-5"><label class="form-label">Área / espacio específico <span class="text-body-secondary">(opcional)</span></label><select class="form-select" name="area_id" id="cameraArea"><option value="">Sin área específica</option><?php foreach($areas as $a):?><option value="<?=$a['id']?>" data-property-id="<?=e((string)($a['property_id']??''))?>"><?=e($a['name'])?> · <?=e(area_scope_label((string)($a['scope_type']??'common')))?> · <?=e(area_usage_label((string)($a['usage_type']??'general')))?></option><?php endforeach;?></select><div class="form-text" id="cameraAreaHelp">Selecciona primero la ubicación estructural para ver sólo sus áreas.</div></div>
<div class="col-md-2"><label class="form-label">Orden</label><input class="form-control" type="number" min="0" max="9999" name="display_order" id="cameraDisplayOrder" value="100"><div class="form-text">Menor aparece primero.</div></div>
<div class="col-md-6 d-flex align-items-end"><div class="d-flex flex-wrap gap-3 pb-2"><label class="form-check"><input class="form-check-input" type="checkbox" name="live_enabled" id="cameraLive"><span class="form-check-label"><strong>Preparar video en vivo</strong></span></label><label class="form-check"><input class="form-check-input" type="checkbox" name="allow_audio" id="cameraAudio"><span class="form-check-label">Audio</span></label><label class="form-check"><input class="form-check-input" type="checkbox" name="allow_ptz" id="cameraPtz"><span class="form-check-label">PTZ</span></label></div></div>
<div class="col-md-6"><label class="form-check"><input class="form-check-input" type="checkbox" name="allow_recordings" id="cameraRecordings"><span class="form-check-label">Permitir grabaciones cuando el módulo esté habilitado</span></label></div>
<div class="col-12"><label class="form-label"><i class="bi bi-door-open me-1"></i>Puertas / accesos asociados a esta cámara</label><select class="form-select" name="access_point_ids[]" id="cameraAccessPoints" multiple size="<?=min(7,max(3,count($accessOptions)))?>"><?php foreach($accessOptions as $ap):?><option value="<?=e($ap['id'])?>"><?=e((string)($ap['name']??'Acceso'))?><?php if(!empty($ap['area'])||!empty($ap['property_name'])):?> · <?=e((string)($ap['area']?:$ap['property_name']))?><?php endif;?></option><?php endforeach;?></select><div class="form-text">Los accesos seleccionados aparecerán dentro del visor. La apertura sólo se habilita si el usuario tiene permiso y existe una ruta remota compatible.</div></div>
<div class="col-12" id="cameraEdgeNotice" style="display:none"><div class="alert alert-light border mb-0"><i class="bi bi-router me-2"></i>Esta cámara/canal viene de un <strong>Edge Agent</strong>. IP, puerto, usuario, contraseña, RTSP y selección técnica de perfil se editan una sola vez en el Agent. En este Node solo administras su uso dentro de la propiedad.</div></div>
<div class="col-12" id="cameraCpanelNotice" <?=$mediaMode==='cpanel_test'?'':'style="display:none"'?>><div class="alert alert-warning mb-0"><i class="bi bi-info-circle me-2"></i>Mientras el Node esté en <strong>Prueba cPanel</strong>, el residente verá el snapshot real. Marcar “Preparar video en vivo” deja este canal listo para activar WebRTC cuando configuremos el relay público.</div></div>
<div class="col-12" id="cameraTechnicalFields"><div class="row g-3"><div class="col-md-4"><label class="form-label">Estado</label><select class="form-select" name="status" id="cameraStatus"><option value="online">Online</option><option value="offline">Offline</option><option value="maintenance">Mantenimiento</option><option value="disabled">Deshabilitada</option></select></div><div class="col-md-4"><label class="form-label">Modo de stream</label><select class="form-select" name="stream_mode" id="cameraMode"><?php foreach(['onvif'=>'ONVIF','rtsp'=>'RTSP','vendor_api'=>'API fabricante','nvr_channel'=>'Canal NVR','protect'=>'UniFi Protect','other'=>'Otro'] as $v=>$l):?><option value="<?=e($v)?>"><?=e($l)?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Activo del inventario</label><select class="form-select" name="device_id" id="cameraDevice"><option value="">Sin activo vinculado</option><?php foreach($devices as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?> · <?=e($d['device_type'])?></option><?php endforeach;?></select></div></div></div>
</div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar configuración</button></div></form></div></div></div>
<script>
document.addEventListener('DOMContentLoaded',()=>{
  const mediaMode=document.getElementById('mediaMode');
  const syncMediaMode=()=>{const mode=mediaMode?mediaMode.value:'cpanel_test';const external=mode==='external_webrtc';const direct=mode==='edge_direct_webrtc';const fields=document.getElementById('externalRelayFields');const note=document.getElementById('cpanelModeNotice');const directNote=document.getElementById('directEdgeNotice');if(fields)fields.style.display=external?'':'none';if(note)note.style.display=mode==='cpanel_test'?'':'none';if(directNote)directNote.style.display=direct?'':'none';};if(mediaMode){mediaMode.addEventListener('change',syncMediaMode);syncMediaMode();}
  const cameraProperty=document.getElementById('cameraProperty'),cameraArea=document.getElementById('cameraArea');
  const filterCameraAreas=(keepArea='')=>{const pid=String(cameraProperty?.value||'');if(!cameraArea)return;let visible=0;Array.from(cameraArea.options).forEach((o,i)=>{if(i===0){o.hidden=false;o.disabled=false;return;}const ok=pid!==''&&String(o.dataset.propertyId||'')===pid;o.hidden=!ok;o.disabled=!ok;if(ok)visible++;});if(keepArea){const wanted=Array.from(cameraArea.options).find(o=>String(o.value)===String(keepArea)&&!o.disabled);cameraArea.value=wanted?String(keepArea):'';}else if(cameraArea.selectedOptions[0]?.disabled)cameraArea.value='';const help=document.getElementById('cameraAreaHelp');if(help)help.textContent=pid===''?'Selecciona primero la ubicación estructural para ver sus áreas.':(visible?`${visible} área(s) disponible(s) en esta ubicación.`:'Esta ubicación no tiene áreas. Puedes dejar la cámara directamente en la estructura.');};
  cameraProperty?.addEventListener('change',()=>filterCameraAreas(''));
  const modal=document.getElementById('cameraModal');if(modal)modal.addEventListener('show.bs.modal',e=>{let d={};try{d=JSON.parse(e.relatedTarget?.dataset.json||'{}')}catch(x){};for(const [id,key,def] of [['cameraId','id',''],['cameraName','name',''],['cameraResidentName','resident_name',''],['cameraDisplayOrder','display_order','100'],['cameraStatus','status','offline'],['cameraMode','stream_mode','onvif'],['cameraVisibility','resident_visibility','none'],['cameraDevice','device_id','']])document.getElementById(id).value=d[key]??def;const locationId=d.property_id||d.area_property_id||'';if(cameraProperty)cameraProperty.value=locationId;filterCameraAreas(d.area_id||'');for(const [id,key] of [['cameraRecordings','allow_recordings'],['cameraAudio','allow_audio'],['cameraPtz','allow_ptz'],['cameraLive','live_enabled']])document.getElementById(id).checked=!!Number(d[key]||0);const edge=(d.source_scope||'node')==='edge';document.getElementById('cameraTechnicalFields').style.display=edge?'none':'';document.getElementById('cameraEdgeNotice').style.display=edge?'':'none';document.getElementById('cameraSourceNote').textContent=edge?'Administrada técnicamente por '+(d.managed_by||'Edge Agent'):'Administrada directamente por el Property Node';const sync=document.getElementById('cameraEdgeNameSync'),follow=document.getElementById('cameraFollowEdgeName'),tech=document.getElementById('cameraEdgeTechnicalName');if(sync)sync.style.display=edge?'':'none';if(follow)follow.checked=edge&&String(d.name_sync_mode||'edge')==='edge';if(tech)tech.textContent=d.edge_name||d.name||'—';const linked=new Set((d.access_point_ids||[]).map(Number));const sel=document.getElementById('cameraAccessPoints');if(sel)Array.from(sel.options).forEach(o=>o.selected=linked.has(Number(o.value)));});
});

// presetNewCameraContext
if(<?= $presetNew?'true':'false' ?>){const m=document.getElementById('cameraModal');if(m){const a=document.getElementById('cameraArea'),p=document.getElementById('cameraProperty');const wanted='<?= (int)$presetAreaId ?>';if(wanted&&a){const o=Array.from(a.options).find(x=>x.value===wanted);if(o&&p)p.value=o.dataset.propertyId||'';}filterCameraAreas(wanted);bootstrap.Modal.getOrCreateInstance(m).show();}}
</script><?php endif;?>
